#!/usr/bin/env python3
"""Generate runtime version constants from product.json."""

from pathlib import Path
import argparse
import json
import re

ROOT = Path(__file__).resolve().parents[1]


def sync(check=False):
    product = json.loads((ROOT / "product.json").read_text())
    version = product["version"]
    if not re.fullmatch(r"\d+\.\d+\.\d+", version):
        raise ValueError("Use a three-part release version")
    outputs = {
        "native-host/mhm/version.py": f'# Generated by scripts/sync_version.py.\nVERSION = "{version}"\n',
        "setup/_version.py": f'# Generated by scripts/sync_version.py.\nVERSION = "{version}"\n',
        "extension/lib/version.js": f'// Generated by scripts/sync_version.py.\nexport const VERSION = "{version}";\n',
    }
    host, firefox = product["nativeHost"], product["firefoxId"]
    outputs["native-host/mhm/identity.py"] = (
        f'# Generated by scripts/sync_version.py.\nNATIVE_HOST = "{host}"\n'
    )
    outputs["setup/_identity.py"] = (
        f'# Generated by scripts/sync_version.py.\nNATIVE_HOST = "{host}"\nFIREFOX_ID = "{firefox}"\n'
    )
    outputs["extension/background/identity.js"] = (
        f'// Generated by scripts/sync_version.py.\nconst MHM_NATIVE_HOST = "{host}";\n'
    )
    outputs["extension/lib/identity.js"] = (
        f'// Generated by scripts/sync_version.py.\nexport const FIREFOX_ID = "{firefox}";\n'
    )
    package = json.loads((ROOT / "extension/package.json").read_text())
    package["version"] = version
    outputs["extension/package.json"] = json.dumps(package, indent=2) + "\n"
    manifest = json.loads((ROOT / "extension/manifest.json").read_text())
    manifest["version"] = version
    outputs["extension/manifest.json"] = json.dumps(manifest, indent=2) + "\n"
    stale = []
    for relative, text in outputs.items():
        path = ROOT / relative
        if not path.exists() or path.read_text() != text:
            stale.append(relative)
            if not check:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(text)
    if check and stale:
        raise SystemExit("Run scripts/sync_version.py to update: " + ", ".join(stale))


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    sync(parser.parse_args().check)
